/*
 * A007986  Co-growth function of the symmetric group S_3 generated by 6
 *          generators together with their inverses, with the relations
 *          sending each generator to a different element of the group
 *          (counting only reduced words).
 * https://oeis.org/A007986
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = 11*a(n-1) - 11*a(n-2) + 121*a(n-3), a(1) = 2, a(2) = 12,
 *            a(3) = 242
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 9, u64 n <= 19, u128 n <= 37,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    if (n == 1) return 2;
    if (n == 2) return 12;
    if (n == 3) return 242;
    
    seq_t a_nm1 = 242;
    seq_t a_nm2 = 12;
    seq_t a_nm3 = 2;
    
    for (idx_t i = 4; i <= n; i++) {
        seq_t a_n = 11 * a_nm1 - 11 * a_nm2 + 121 * a_nm3;
        a_nm3 = a_nm2;
        a_nm2 = a_nm1;
        a_nm1 = a_n;
    }
    
    return a_nm1;
}
